#!/bin/bash
# Sentinel release @REL@ (commit @COMMIT@). Generated by deploy/scripts/package_release.py: do not edit.
# Upload this script and sentinel-app.tgz to /tmp, then run:  sudo bash /tmp/sentinel-release.sh
# Step 1 changes nothing: it checks the package checksum and the sec-bundle pass (decision 0006).
set -euo pipefail
# SEC_BUNDLE_BEGIN (filled in by package_release.py, do not edit)
SEC_PASS="" SEC_BIND="" SEC_AT=0
# SEC_BUNDLE_END

sec_bundle_check() {
  [[ "$SEC_PASS" =~ ^[0-9a-f]{64}$ ]] || { echo "No sec-bundle pass in this script: it was not packaged after a pass. Nothing was changed."; false; }
  (( $(date +%s) - SEC_AT < 86400 )) || { echo "The sec-bundle pass in this script is over 24 hours old. Repackage it. Nothing was changed."; false; }
  local got
  got=$(printf '%s%s' "$SEC_PASS" "$(sha256sum "$@" | cut -d' ' -f1 | tr -d '\n')" | sha256sum | cut -d' ' -f1)
  [ "$got" = "$SEC_BIND" ] || { echo "The sec-bundle pass does not match these packages. Nothing was changed."; false; }
  echo "sec-bundle pass ${SEC_PASS:0:12}… matches these packages"
}

[ "$(id -u)" = 0 ] || { echo "run with sudo"; exit 1; }

echo "=== 1. checks (nothing changed yet) ==="
cd /tmp
sha256sum -c <<'SUMS'
SUMS
sec_bundle_check sentinel-app.tgz

echo "=== 2. unpack ==="
rm -rf /tmp/sentinel
install -d -m 755 /tmp/sentinel
tar xzf sentinel-app.tgz -C /tmp/sentinel
[ -f /tmp/sentinel/manage.py ] || { echo "package has no manage.py"; exit 1; }

echo "=== 3. install ==="
bash /tmp/sentinel/deploy/install.sh

echo "=== 4. clean up ==="
rm -rf /tmp/sentinel /tmp/sentinel-app.tgz
echo "release @REL@ live. Undo with: sudo bash /opt/sentinel/deploy/rollback.sh"
